const SHARED_BLOCK_MODEL="window.ML_BLOCK_MODEL=(()=>{function counts(n){if(Array.isArray(n))return n;n=Math.max(0,Math.floor(Number(n)||0));return[Math.floor(n/100),Math.floor(n%100/10),n%10]}function picture(n,basis=[n]){const sizes=basis.map(counts),max=[0,1,2].map(i=>Math.max(0,...sizes.map(a=>a[i]))),u=8,gap=3,pad=6,widths=max.map((v,i)=>v?Math.min(i===0?3:5,v)*(i===0?10:1)*u+(Math.min(i===0?3:5,v)-1)*gap:0),starts=[];let w=pad;for(const size of widths){starts.push(w);if(size)w+=size+15}w=Math.max(80,w);const heights=max.map((v,i)=>v?Math.ceil(v/(i===0?3:5))*(i===2?u:10*u)+(Math.ceil(v/(i===0?3:5))-1)*gap:0),h=Math.max(14,...heights)+pad*2;let out='';counts(n).forEach((count,index)=>{const cols=index===0?3:5,bw=(index===0?10:1)*u,bh=(index===2?1:10)*u;for(let i=0;i<count;i++){const x=starts[index]+(i%cols)*(bw+gap),y=pad+Math.floor(i/cols)*(bh+gap),fill=['#e8bc55','#75b9d9','#e5a07a'][index];out+='<rect data-block-value=\"'+[100,10,1][index]+'\" x=\"'+x+'\" y=\"'+y+'\" width=\"'+bw+'\" height=\"'+bh+'\" fill=\"'+fill+'\" stroke=\"#537b83\" stroke-width=\".55\"/>';if(index<2)for(let k=1;k<10;k++){out+='<path d=\"M'+x+' '+(y+k*u)+'h'+bw+'\" stroke=\"#778377\" stroke-width=\".45\"/>';if(index===0)out+='<path d=\"M'+(x+k*u)+' '+y+'v'+bh+'\" stroke=\"#778377\" stroke-width=\".45\"/>'}}});if(counts(n).every(v=>!v))out='<text x=\"'+w/2+'\" y=\"'+h/2+'\" text-anchor=\"middle\" font-size=\"20\" fill=\"#183f45\">0 blocks</text>';return'<svg class=\"oa-block-picture\" viewBox=\"0 0 '+(w+pad)+' '+h+'\" role=\"img\" aria-label=\"'+n+' base-ten blocks\">'+out+'</svg>'}return{picture,counts}})();";
const SHARING_WORK="if(window.ML_CONFIG.shareOnly){for(const x of questions){if(x.kind==='fraction'){x.a9WasFraction=true;x.kind='share';x.title='Share the apples equally';x.total=ML_CONFIG.shareTotal;x.groups=grade===3?5:2;x.item='apple';x.answer=Math.floor(x.total/x.groups);x.remainder=x.total%x.groups;x.codes=ML_CONFIG.curriculumAlignment.codes;x.prompt='Share '+x.total+' whole apples equally among '+x.groups+' children.';x.directions='Choose 2, 4 or 5 children. Drag apples to the pads or tap a pad to place one. Put whole apples that cannot be shared equally in Extra.';}}}\nconst q=()=>questions[index],work=()=>{const x=q(),s=state.questions[x.id]||=(M.create(x));if(ML_CONFIG.shareOnly){if(s.a9Sharers){x.groups=s.a9Sharers;x.answer=Math.floor(x.total/x.groups);x.remainder=x.total%x.groups;}if(!s.a9ShareOnly){s.a9PreviousFraction={selected:structuredClone(s.selected),answers:structuredClone(s.answers),sharePads:structuredClone(s.a8SharePads||{}),actions:structuredClone(s.actions)};const fresh=M.create(x);s.tokens=fresh.tokens.map((t,i)=>({...t,loc:Number.isInteger(s.a8SharePads?.[i])&&s.a8SharePads[i]<x.groups?'g'+s.a8SharePads[i]:'bank'}));s.next=fresh.next;s.a9ShareOnly=true;s.a9Sharers=x.groups;}x.prompt='Share '+x.total+' whole apples equally among '+x.groups+' children.';x.key=x.answer+' whole apples each; '+x.remainder+' whole apples in Extra.';}return s};";
const SHARING_EVENTS="document.addEventListener('click',e=>{const button=e.target.closest('[data-a9-sharers]');if(!button||!ML_CONFIG.shareOnly)return;e.preventDefault();e.stopImmediatePropagation();const x=q(),s=work(),n=+button.dataset.a9Sharers;if(![2,4,5].includes(n)||n===x.groups)return;s.a9BySharers||={};s.a9BySharers[x.groups]={tokens:structuredClone(s.tokens),answers:structuredClone(s.answers)};x.groups=n;x.answer=Math.floor(x.total/n);x.remainder=x.total%n;const prior=s.a9BySharers[n],fresh=M.create(x);s.tokens=prior?structuredClone(prior.tokens):fresh.tokens;s.answers=prior?structuredClone(prior.answers):{};s.next=Math.max(fresh.next,s.next);s.a9Sharers=n;s.history=[];changed('choose number of sharers',{sharers:n});render();},true);\n";
